ad0b58","definition":"CREATE INDEX \"IDX_498848f165da96907ba6ad0b58\" ON public.xpert_project_pipeline_task_link USING btree (\"tenantId\")","valid":true},{"table":"xpert_project_pipeline_task_link","name":"IDX_5231afd788655945bb4a76af74","definition":"CREATE UNIQUE INDEX \"IDX_5231afd788655945bb4a76af74\" ON public.xpert_project_pipeline_task_link USING btree (\"nodeInstanceId\", \"taskId\")","valid":true},{"table":"xpert_project_pipeline_task_link","name":"IDX_8f251699d90fad1516ca76d7ce","definition":"CREATE INDEX \"IDX_8f251699d90fad1516ca76d7ce\" ON public.xpert_project_pipeline_task_link USING btree (\"organizationId\")","valid":true},{"table":"xpert_project_task","name":"IDX_2253ba272431f0c6d1a035bbad","definition":"CREATE INDEX \"IDX_2253ba272431f0c6d1a035bbad\" ON public.xpert_project_task USING btree (\"tenantId\")","valid":true},{"table":"xpert_project_task","name":"IDX_9d9cf8b6c34bd80b3eb420fa95","definition":"CREATE INDEX \"IDX_9d9cf8b6c34bd80b3eb420fa95\" ON public.xpert_project_task USING btree (\"organizationId\")","valid":true},{"table":"xpert_project_task","name":"IDX_a802b24395db7adfbf5c627785","definition":"CREATE UNIQUE INDEX \"IDX_a802b24395db7adfbf5c627785\" ON public.xpert_project_task USING btree (\"projectId\", \"providerKey\", \"sourceKey\")","valid":true},{"table":"xpert_project_task_execution","name":"IDX_42a2196724bd0c1c68acd307a4","definition":"CREATE UNIQUE INDEX \"IDX_42a2196724bd0c1c68acd307a4\" ON public.xpert_project_task_execution USING btree (\"taskId\", \"sourceKey\")","valid":true},{"table":"xpert_project_task_execution","name":"IDX_5f6ffee42e79426450e5e40812","definition":"CREATE INDEX \"IDX_5f6ffee42e79426450e5e40812\" ON public.xpert_project_task_execution USING btree (\"organizationId\")","valid":true},{"table":"xpert_task_execution","name":"IDX_4222a2ce255639c5818ac21756","definition":"CREATE INDEX \"IDX_4222a2ce255639c5818ac21756\" ON public.xpert_task_execution USING btree (\"organizationId\")","valid":true},{"table":"xpert_task_execution","name":"IDX_b5e00ff54a7231e5dc71487bee","definition":"CREATE INDEX \"IDX_b5e00ff54a7231e5dc71487bee\" ON public.xpert_task_execution USING btree (\"tenantId\")","valid":true}]}$catalog$::jsonb AS catalog),
columns AS (
  SELECT c.relname AS "table", a.attname AS name, format_type(a.atttypid,a.atttypmod) AS type,
    a.attnotnull AS "notNull", pg_get_expr(d.adbin,d.adrelid) AS "default"
  FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
  WHERE n.nspname=current_schema() AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped
),
constraints AS (
  SELECT t.relname AS "table", c.conname AS name, pg_get_constraintdef(c.oid) AS definition,
    c.convalidated AS validated FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
),
indexes AS (
  SELECT t.relname AS "table", c.relname AS name, pg_get_indexdef(i.indexrelid) AS definition, i.indisvalid AS valid
  FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
)
SELECT 'column:'||e."table"||'.'||e.name AS missing FROM expected,
  jsonb_to_recordset(catalog->'columns') AS e("table" text,name text,type text,"notNull" boolean,"default" text)
WHERE NOT EXISTS (SELECT 1 FROM columns a WHERE a."table"=e."table" AND a.name=e.name AND a.type=e.type
  AND a."notNull"=e."notNull" AND a."default" IS NOT DISTINCT FROM e."default")
UNION ALL
SELECT 'constraint:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'constraints') AS e("table" text,name text,definition text,validated boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM constraints a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.validated=e.validated)
UNION ALL
SELECT 'index:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'indexes') AS e("table" text,name text,definition text,valid boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM indexes a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.valid=e.valid);
